import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';

function JobForm({ job, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    title: '', role: '', skillset: '', ctc: '', location: '',
    experience: '', jobType: 'Full-time', department: '', description: '',
    responsibilities: '', qualifications: '', benefits: '', deadline: ''
  });

  useEffect(() => {
    if (job) setFormData(job);
  }, [job]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = () => {
    if (!formData.title || !formData.role || !formData.skillset || !formData.ctc || !formData.location || !formData.experience || !formData.description) {
      alert('Please fill all required fields');
      return;
    }
    onSubmit(formData);
  };

  const resetForm = () => {
    setFormData({
      title: '', role: '', skillset: '', ctc: '', location: '',
      experience: '', jobType: 'Full-time', department: '', description: '',
      responsibilities: '', qualifications: '', benefits: '', deadline: ''
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-start justify-center overflow-y-auto">
      <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full m-6">
        {/* Header */}
        <div className="flex items-center justify-between border-b p-6 rounded-t-lg">
          <h2 className="text-2xl font-bold">{job ? 'Edit Job' : 'Add New Job'}</h2>
          <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Form Content */}
        <div className="p-6 max-h-[calc(100vh-200px)] overflow-y-auto grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-medium mb-1">Job Title *</label>
            <input type="text" name="title" value={formData.title} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Role/Position *</label>
            <input type="text" name="role" value={formData.role} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Skillset *</label>
            <input type="text" name="skillset" value={formData.skillset} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">CTC *</label>
            <input type="text" name="ctc" value={formData.ctc} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Location *</label>
            <input type="text" name="location" value={formData.location} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Experience *</label>
            <input type="text" name="experience" value={formData.experience} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Job Type</label>
            <select name="jobType" value={formData.jobType} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500">
              <option>Full-time</option>
              <option>Part-time</option>
              <option>Contract</option>
              <option>Internship</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Department</label>
            <input type="text" name="department" value={formData.department} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium mb-1">Deadline</label>
            <input type="date" name="deadline" value={formData.deadline} onChange={handleChange} className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium mb-1">Description *</label>
            <textarea name="description" value={formData.description} onChange={handleChange} rows="4" className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium mb-1">Responsibilities</label>
            <textarea name="responsibilities" value={formData.responsibilities} onChange={handleChange} rows="3" className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium mb-1">Qualifications</label>
            <textarea name="qualifications" value={formData.qualifications} onChange={handleChange} rows="3" className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium mb-1">Benefits & Perks</label>
            <textarea name="benefits" value={formData.benefits} onChange={handleChange} rows="3" className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"/>
          </div>
        </div>

        {/* Footer Buttons */}
        <div className="flex gap-4 p-6 border-t bg-gray-50 rounded-b-lg">
          <button onClick={handleSubmit} className="flex-1 bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700">
            {job ? 'Update Job' : 'Add Job'}
          </button>
          <button onClick={resetForm} className="flex-1 bg-gray-200 text-gray-700 py-3 rounded-lg hover:bg-gray-300">
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

export default JobForm;
